+++ b//Users/melvynx/Developer/agent-benchmarks/benchmarks/distributed-systems-playground/2026-09-21-cursor-agent-grok-4-7-high/index.html
@@ -1,0 +1,1889 @@
+<!DOCTYPE html>
+<html lang="en">
+<head>
+<meta charset="utf-8">
+<meta name="viewport" content="width=device-width, initial-scale=1">
+<meta name="color-scheme" content="dark">
+<title>Grok 4.7</title>
+<style>
+  :root {
+    --bg: #10140f;
+    --bg-2: #171c14;
+    --bg-3: #20261b;
+    --ink: #f4f0e4;
+    --muted: #a4ab95;
+    --line: #343b2c;
+    --amber: #f0b429;
+    --mint: #c6d67b;
+    --clay: #e07a5f;
+    --steel: #86b0a6;
+    --copper: #d08a45;
+    --shadow: 0 16px 40px rgba(0, 0, 0, 0.28);
+  }
+  * { box-sizing: border-box; }
+  html, body { margin: 0; height: 100%; background: var(--bg); color: var(--ink); }
+  body {
+    font: 13px/1.4 "Segoe UI", ui-sans-serif, system-ui, sans-serif;
+    background:
+      radial-gradient(900px 420px at 0% -10%, rgba(208, 138, 69, 0.16), transparent 55%),
+      radial-gradient(800px 480px at 100% 0%, rgba(134, 176, 166, 0.12), transparent 50%),
+      var(--bg);
+    -webkit-font-smoothing: antialiased;
+  }
+  button, input { font: inherit; color: inherit; }
+  button {
+    background: var(--bg-3);
+    border: 1px solid var(--line);
+    border-radius: 4px;
+    padding: 6px 8px;
+    cursor: pointer;
+  }
+  button:hover { border-color: var(--mint); }
+  button[aria-pressed="true"] {
+    border-color: var(--amber);
+    color: var(--amber);
+    background: #2c2818;
+  }
+  button:disabled { opacity: 0.45; cursor: not-allowed; }
+  :focus-visible { outline: 2px solid var(--amber); outline-offset: 2px; }
+  input[type="range"] { width: 100%; accent-color: var(--amber); }
+  input[type="number"] {
+    width: 100%;
+    background: #12160f;
+    border: 1px solid var(--line);
+    border-radius: 4px;
+    padding: 6px 8px;
+  }
+  h1, h2, p { margin: 0; }
+  .app { min-height: 100%; display: flex; flex-direction: column; gap: 10px; padding: 12px; }
+  header.top {
+    display: flex;
+    justify-content: space-between;
+    gap: 16px;
+    align-items: stretch;
+    padding-bottom: 8px;
+    border-bottom: 1px solid var(--line);
+  }
+  .brand { display: flex; gap: 12px; align-items: center; min-width: 220px; }
+  .mark {
+    width: 36px; height: 36px; flex: none;
+    background:
+      linear-gradient(135deg, transparent 48%, var(--amber) 48% 52%, transparent 52%),
+      linear-gradient(45deg, transparent 48%, var(--mint) 48% 52%, transparent 52%);
+    border: 1px solid var(--line);
+  }
+  h1 {
+    font-family: Palatino, "Palatino Linotype", "Iowan Old Style", Georgia, serif;
+    font-size: 34px;
+    font-weight: 600;
+    letter-spacing: -0.03em;
+    line-height: 0.95;
+  }
+  .kicker {
+    margin-top: 4px;
+    color: var(--muted);
+    font-size: 11px;
+    letter-spacing: 0.16em;
+    text-transform: uppercase;
+  }
+  .strip {
+    display: flex;
+    flex-wrap: wrap;
+    gap: 8px 18px;
+    margin: 0;
+    align-items: end;
+    justify-content: flex-end;
+  }
+  .strip div { min-width: 92px; }
+  .strip dt {
+    color: var(--muted);
+    font-size: 10px;
+    letter-spacing: 0.14em;
+    text-transform: uppercase;
+  }
+  .strip dd {
+    margin: 2px 0 0;
+    font: 600 18px/1 ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace;
+  }
+  .layout {
+    flex: 1;
+    min-height: 0;
+    display: grid;
+    grid-template-columns: 228px minmax(0, 1fr) 300px;
+    gap: 10px;
+  }
+  .controls, .side, .panel {
+    background: rgba(23, 28, 20, 0.92);
+    border: 1px solid var(--line);
+    border-radius: 8px;
+    box-shadow: var(--shadow);
+  }
+  .controls { padding: 10px; overflow: auto; display: flex; flex-direction: column; gap: 10px; }
+  .group { display: flex; flex-direction: column; gap: 6px; }
+  .group h2, .panel h2, .node h2 {
+    font-size: 10px;
+    letter-spacing: 0.14em;
+    text-transform: uppercase;
+    color: var(--muted);
+    font-weight: 650;
+  }
+  .row { display: flex; flex-wrap: wrap; gap: 6px; }
+  .row > button, .scenarios button { flex: 1 1 auto; }
+  .scenarios { display: grid; gap: 6px; }
+  label.slider { display: grid; gap: 2px; color: var(--muted); font-size: 11px; }
+  label.slider strong { color: var(--ink); font-weight: 600; }
+  main.stage {
+    min-width: 0;
+    display: grid;
+    grid-template-rows: minmax(560px, 1fr) 118px 148px;
+    gap: 10px;
+  }
+  .topo {
+    position: relative;
+    min-height: 560px;
+    border-radius: 8px;
+    background:
+      linear-gradient(rgba(255,255,255,0.025) 1px, transparent 1px),
+      linear-gradient(90deg, rgba(255,255,255,0.025) 1px, transparent 1px),
+      rgba(14, 18, 12, 0.92);
+    background-size: 28px 28px, 28px 28px, auto;
+    box-shadow: inset 0 0 0 1px var(--line), var(--shadow);
+    overflow: hidden;
+  }
+  .overlay { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
+  #edges { z-index: 1; pointer-events: none; }
+  .node {
+    position: absolute;
+    z-index: 2;
+    padding: 8px;
+    background: rgba(23, 28, 20, 0.94);
+    border: 1px solid var(--line);
+    border-radius: 6px;
+    box-shadow: 0 8px 20px rgba(0,0,0,0.18);
+    overflow: hidden;
+  }
+  .node header { display: flex; justify-content: space-between; gap: 6px; align-items: center; margin-bottom: 4px; }
+  .badge {
+    flex: none;
+    border: 1px solid var(--line);
+    border-radius: 99px;
+    padding: 1px 6px;
+    font: 10px/1.4 ui-monospace, Menlo, Consolas, monospace;
+    color: var(--mint);
+  }
+  .node[data-state="nominal"] { box-shadow: inset 3px 0 0 var(--mint); }
+  .node[data-state="degraded"] {
+    box-shadow: inset 3px 0 0 var(--amber);
+    background-image: repeating-linear-gradient(0deg, transparent, transparent 7px, rgba(240,180,41,0.07) 7px, rgba(240,180,41,0.07) 8px);
+  }
+  .node[data-state="degraded"] .badge { color: var(--amber); border-color: #6a5a2a; }
+  .node[data-state="throttled"] {
+    box-shadow: inset 3px 0 0 var(--amber);
+    background-image: repeating-linear-gradient(90deg, transparent, transparent 5px, rgba(240,180,41,0.1) 5px, rgba(240,180,41,0.1) 6px);
+  }
+  .node[data-state="throttled"] .badge { color: var(--amber); }
+  .node[data-state="failed"] {
+    box-shadow: inset 3px 0 0 var(--clay);
+    background-image: repeating-linear-gradient(-45deg, transparent, transparent 6px, rgba(224,122,95,0.1) 6px, rgba(224,122,95,0.1) 7px);
+  }
+  .node[data-state="failed"] .badge { color: var(--clay); border-color: #6e3d32; }
+  .nb { font: 11px/1.35 ui-monospace, Menlo, Consolas, monospace; color: var(--ink); }
+  .nb .sub { color: var(--muted); }
+  .meter { height: 4px; background: #2a3124; border-radius: 99px; margin: 4px 0; overflow: hidden; }
+  .meter > i { display: block; height: 100%; background: var(--mint); width: 0; }
+  .meter > i.warn { background: var(--amber); }
+  .meter > i.bad { background: var(--clay); }
+  .chips { display: flex; flex-wrap: wrap; gap: 3px; margin-top: 4px; }
+  .chip {
+    border: 1px solid var(--line);
+    background: transparent;
+    border-radius: 3px;
+    padding: 1px 4px;
+    font: 10px/1.4 ui-monospace, Menlo, Consolas, monospace;
+    cursor: pointer;
+  }
+  .chip[aria-pressed="true"], .pkt.selected { filter: drop-shadow(0 0 0 var(--amber)); }
+  .chip[aria-pressed="true"] { border-color: var(--amber); color: var(--amber); }
+  #packets { z-index: 4; pointer-events: none; }
+  #packets .pkt { pointer-events: auto; cursor: pointer; }
+  .pkt-read { fill: none; stroke: var(--steel); stroke-width: 1.6; }
+  .pkt-write { fill: none; stroke: var(--amber); stroke-width: 1.6; }
+  .pkt-retry { fill: none; stroke: var(--copper); stroke-width: 1.6; }
+  .pkt-hit { fill: none; stroke: var(--mint); stroke-width: 1.6; }
+  .pkt-fail, .pkt-dead { fill: none; stroke: var(--clay); stroke-width: 1.6; }
+  .pkt-dupe { fill: none; stroke: var(--ink); stroke-width: 1.4; stroke-dasharray: 2 1; }
+  .pkt-repl { fill: none; stroke: var(--steel); stroke-width: 1.4; }
+  .pkt text { fill: var(--ink); font: 8px/1 ui-monospace, Menlo, monospace; text-anchor: middle; pointer-events: none; }
+  .legend { margin-top: 4px; color: var(--muted); font: 10px/1.4 ui-monospace, Menlo, monospace; }
+  .charts { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; min-height: 0; }
+  .charts figure {
+    margin: 0; min-width: 0;
+    background: rgba(23, 28, 20, 0.92);
+    border: 1px solid var(--line);
+    border-radius: 8px;
+    padding: 6px 8px 4px;
+    display: grid;
+    grid-template-rows: auto 1fr;
+  }
+  .charts figcaption {
+    color: var(--muted);
+    font-size: 10px;
+    letter-spacing: 0.12em;
+    text-transform: uppercase;
+  }
+  canvas { width: 100%; height: 78px; display: block; }
+  .logwrap, .panel { min-height: 0; display: flex; flex-direction: column; }
+  .logwrap { background: rgba(23, 28, 20, 0.92); border: 1px solid var(--line); border-radius: 8px; overflow: hidden; }
+  .logwrap h2, .panel h2 { padding: 8px 10px 0; }
+  #log, #inspector, #dlq-list, #diag-list {
+    margin: 0; padding: 6px 10px 10px; overflow: auto; min-height: 0;
+    font: 11px/1.45 ui-monospace, Menlo, Consolas, monospace;
+    list-style: none;
+  }
+  #log { height: 100%; }
+  #log li[data-level="warn"] { color: var(--amber); }
+  #log li[data-level="error"] { color: var(--clay); }
+  .side { display: grid; grid-template-rows: minmax(180px, 1fr) minmax(140px, 180px) auto; gap: 10px; background: transparent; border: 0; box-shadow: none; min-height: 0; }
+  .panel { padding-bottom: 8px; overflow: hidden; }
+  .timeline { display: grid; gap: 3px; }
+  .timeline div { border-left: 2px solid var(--line); padding: 0 0 4px 8px; }
+  #diag-summary { color: var(--muted); font-weight: 500; letter-spacing: 0; text-transform: none; }
+  #diag-list li.ok { color: var(--mint); }
+  #diag-list li.bad { color: var(--clay); }
+  .doc { color: var(--muted); font-size: 11px; padding: 0 10px; }
+  #node-clients { left: 1.2%; top: 16%; width: 15%; }
+  #node-gateway { left: 18%; top: 16%; width: 16.5%; }
+  #node-queue { left: 36.2%; top: 16%; width: 16%; }
+  #node-workers { left: 54%; top: 6%; width: 20%; max-height: 46%; }
+  #node-primary { left: 76%; top: 3%; width: 22.5%; max-height: 34%; }
+  #node-replica { left: 76%; top: 38%; width: 22.5%; max-height: 22%; }
+  #node-dlq { left: 1.2%; top: 58%; width: 23%; max-height: 22%; }
+  #node-retry { left: 26%; top: 58%; width: 20%; }
+  #node-cache { left: 48%; top: 58%; width: 26%; max-height: 22%; }
+  #node-obs { left: 1.2%; top: 82%; width: 97.2%; max-height: 16%; }
+  @media (max-width: 1120px) {
+    .layout { grid-template-columns: 1fr; }
+    .controls { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); }
+    .side { grid-template-columns: 1fr 1fr; grid-template-rows: auto auto; }
+    .side .diag { grid-column: 1 / -1; }
+    main.stage { grid-template-rows: 640px 140px 160px; }
+  }
+  @media (max-width: 760px) {
+    h1 { font-size: 28px; }
+    header.top { flex-direction: column; }
+    .strip { justify-content: flex-start; }
+    .controls { grid-template-columns: 1fr; }
+    .charts { grid-template-columns: 1fr 1fr; }
+    .side { grid-template-columns: 1fr; }
+    main.stage { grid-template-rows: 980px auto 180px; }
+    .topo { min-height: 980px; height: 980px; }
+    #node-clients { left: 2%; top: 1%; width: 47%; }
+    #node-gateway { left: 51%; top: 1%; width: 47%; }
+    #node-queue { left: 2%; top: 15%; width: 47%; }
+    #node-workers { left: 51%; top: 15%; width: 47%; max-height: 18%; }
+    #node-primary { left: 2%; top: 35%; width: 47%; max-height: 16%; }
+    #node-replica { left: 51%; top: 35%; width: 47%; max-height: 16%; }
+    #node-cache { left: 2%; top: 53%; width: 47%; }
+    #node-retry { left: 51%; top: 53%; width: 47%; }
+    #node-dlq { left: 2%; top: 69%; width: 96%; }
+    #node-obs { left: 2%; top: 84%; width: 96%; }
+  }
+  @media (prefers-reduced-motion: reduce) {
+    * { animation: none !important; transition: none !important; }
+  }
+</style>
+</head>
+<body>
+<div class="app">
+  <header class="top">
+    <div class="brand">
+      <span class="mark" aria-hidden="true"></span>
+      <div>
+        <h1>Grok 4.7</h1>
+        <p class="kicker">Discrete-time operations console</p>
+      </div>
+    </div>
+    <dl class="strip">
+      <div><dt>Simulated</dt><dd id="strip-time">00:00.00</dd></div>
+      <div><dt>Completed</dt><dd id="strip-done">0</dd></div>
+      <div><dt>Dupes blocked</dt><dd id="strip-dupes">0</dd></div>
+      <div><dt>Cache hit</dt><dd id="strip-hit">0%</dd></div>
+      <div><dt>Scenario</dt><dd id="strip-scenario">Healthy baseline</dd></div>
+      <div><dt id="strip-play-label">Playing</dt><dd id="strip-speed">1×</dd></div>
+    </dl>
+  </header>
+  <div class="layout">
+    <aside class="controls" aria-label="Operator controls">
+      <div class="group">
+        <h2>Transport</h2>
+        <div class="row">
+          <button type="button" id="btn-play" aria-pressed="true">Pause</button>
+          <button type="button" id="btn-step">Step 50ms</button>
+        </div>
+        <div class="row" role="group" aria-label="Simulation speed">
+          <button type="button" data-speed="0.5">0.5×</button>
+          <button type="button" data-speed="1" aria-pressed="true">1×</button>
+          <button type="button" data-speed="2">2×</button>
+          <button type="button" data-speed="4">4×</button>
+        </div>
+      </div>
+      <div class="group">
+        <h2>Seed</h2>
+        <input id="seed" type="number" min="0" step="1" value="7" aria-label="Seed" spellcheck="false">
+        <button type="button" id="btn-reset">Reset</button>
+      </div>
+      <div class="group">
+        <h2>Load</h2>
+        <label class="slider">Traffic <strong id="traffic-val">4/s</strong>
+          <input id="traffic" type="range" min="0" max="40" step="1" value="4">
+        </label>
+        <label class="slider">Workers <strong id="worker-val">4</strong>
+          <input id="workers" type="range" min="1" max="12" step="1" value="4">
+        </label>
+      </div>
+      <div class="group">
+        <h2>Inject</h2>
+        <div class="row">
+          <button type="button" id="btn-one">Send one</button>
+          <button type="button" id="btn-burst">Burst</button>
+          <button type="button" id="btn-dupes">Burst + duplicates</button>
+        </div>
+      </div>
+      <div class="group">
+        <h2>Faults</h2>
+        <div class="row">
+          <button type="button" id="btn-db-fail">Fail primary</button>
