+      if (!req) html = "<p>Request " + esc(sel.id) + " aged out of the live window.</p>";
+      else {
+        sig += ":" + req.status + ":" + req.history.length + ":" + req.attempt;
+        html = "<div><strong>" + esc(req.id) + "</strong> " + esc(req.op) + " " + esc(req.key) + "</div>" +
