+          '<div class="sub">idem ' + esc(req.idempotencyKey) + "</div>" +
+          (req.stale ? '<div>stale read</div>' : "") +
+          '<div class="timeline">' + req.history.map((h) => "<div><span class=\"sub\">" + esc(fmtTime(h.t)) + "</span> " + esc(h.message) + "</div>").join("") + "</div>";
