+      html = "<div><strong>" + esc(key) + "</strong></div>" +
+        "<div>primary " + (pri ? "v" + pri.version + " = " + esc(pri.value) + " · " + esc(pri.tenantId) : "absent") + "</div>" +
+        "<div>replica " + (rep ? "v" + rep.version + " = " + esc(rep.value) : "absent") + (stale ? " · stale" : "") + "</div>" +
+        "<div>cache " + (cache ? (cache.expiresAt > s.now ? "v" + cache.version + " exp " + fmtTime(cache.expiresAt) : "expired v" + cache.version) : "empty") + "</div>";
