+    const el = document.getElementById("dlq-list");
+    if (!el) return;
+    const sig = s.dlq.map((d) => d.requestId).join(",") + ":" + (s.selection ? s.selection.id : "");
+    if (el.__sig === sig) return;
+    el.__sig = sig;
+    if (!s.dlq.length) { el.innerHTML = '<p class="sub">Empty. Permanently failed work lands here after ' + MAX_ATTEMPTS + " attempts.</p>"; return; }
+    el.innerHTML = s.dlq.map((d) => {
+      const pressed = s.selection && s.selection.type === "request" && s.selection.id === d.requestId;
