+    if (!summary || !list) return;
+    if (!lastSelfTest) {
+      summary.textContent = "not run";
+      list.innerHTML = "";
+      return;
+    }
+    const passed = lastSelfTest.tests.filter((t) => t.pass).length;
+    summary.textContent = passed + "/" + lastSelfTest.tests.length + (lastSelfTest.passed ? " passed" : " failed");
+    list.innerHTML = lastSelfTest.tests.map((t) => '<li class="' + (t.pass ? "ok" : "bad") + '">' + (t.pass ? "pass" : "fail") + " · " + esc(t.name) + " — " + esc(t.detail) + "</li>").join("");
