+      live.locks.traffic = true;
+      live.trafficRate = Number(e.target.value);
+    });
+    document.getElementById("workers").addEventListener("input", function (e) {
+      setWorkerCount(live, Number(e.target.value));
+    });
+    document.getElementById("btn-one").addEventListener("click", function () { sendRequest(live, {}); });
+    document.getElementById("btn-burst").addEventListener("click", function () { burst(live, 10); });
+    document.getElementById("btn-dupes").addEventListener("click", function () { burstDupes(live); });
+    document.getElementById("btn-db-fail").addEventListener("click", function () { live.locks.db = true; setPrimary(live, false); });
+    document.getElementById("btn-db-recover").addEventListener("click", function () { live.locks.db = true; setPrimary(live, true); });
+    document.getElementById("btn-worker-stop").addEventListener("click", function () { stopOneWorker(live); });
+    document.getElementById("btn-worker-restore").addEventListener("click", function () { restoreOneWorker(live); });
+    document.getElementById("btn-lag-add").addEventListener("click", function () { live.locks.lag = true; setLag(live, 3000); });
+    document.getElementById("btn-lag-clear").addEventListener("click", function () { live.locks.lag = true; setLag(live, 0); });
+    document.getElementById("btn-poison-clear").addEventListener("click", function () { clearPoison(live); });
+    document.getElementById("btn-replay").addEventListener("click", function () {
+      if (live.selection && live.selection.type === "request") replay(live, live.selection.id);
+      else log(live, "dlq", "Select a dead-letter item before replay");
+    });
+    document.getElementById("btn-self-test").addEventListener("click", function () { runSelfTest(); });
+    const speeds = document.querySelectorAll("[data-speed]");
+    for (let i = 0; i < speeds.length; i++) {
+      speeds[i].addEventListener("click", function () { live.speed = Number(this.dataset.speed); });
+    }
+    const scenarios = document.querySelectorAll("[data-scenario]");
+    for (let i = 0; i < scenarios.length; i++) {
+      scenarios[i].addEventListener("click", function () {
+        live = setScenario(live, this.dataset.scenario);
+        syncSeedField();
+      });
+    }
+    document.body.addEventListener("click", function (e) {
+      const replayBtn = e.target.closest("[data-replay]");
+      if (replayBtn) {
+        replay(live, replayBtn.getAttribute("data-replay"));
+        live.selection = { type: "request", id: replayBtn.getAttribute("data-replay") };
+        return;
+      }
+      const sel = e.target.closest("[data-select]");
+      if (!sel) return;
+      const raw = sel.getAttribute("data-select");
+      const i = raw.indexOf(":");
+      live.selection = { type: raw.slice(0, i), id: raw.slice(i + 1) };
+    });
+    document.addEventListener("keydown", function (e) {
+      const tag = e.target && e.target.tagName;
+      if (tag === "INPUT" || tag === "TEXTAREA") return;
+      if (e.key === " " || e.code === "Space") {
+        e.preventDefault();
+        live.playing = !live.playing;
+      } else if (e.key === "." && !e.repeat) step(live, DT);
+    });
+    document.addEventListener("visibilitychange", function () { lastWall = 0; });
+    window.addEventListener("resize", function () { render(); });
+    const api = {
+      reset: function (seed) {
+        live = reset(live, seed);
+        syncSeedField();
+        render();
+      },
+      setScenario: function (name) {
+        if (!SCENARIOS[name]) return false;
+        live = setScenario(live, name);
+        syncSeedField();
+        render();
+        return true;
+      },
+      step: function (milliseconds) { step(live, milliseconds); render(); },
+      sendRequest: function (options) { const id = sendRequest(live, options || {}); render(); return id; },
+      snapshot: function () { return snapshot(live); },
+      runSelfTest: function () { return runSelfTest(); }
+    };
+    window.__DSP__ = api;
+    render();
+    requestAnimationFrame(loop);
+    setTimeout(function () { runSelfTest(); }, 30);
+  }
+  function runSelfTest() {
+    lastSelfTest = executeSelfTest();
+    renderDiag();
+    return lastSelfTest;
+  }
+  boot();
+})();
+</script>
+</body>
+</html>

