page.on("console", (msg) => { if (msg.type() === "error") errors.push(msg.text()); });
await page.setViewportSize({ width: 1440, height: 900 });
await page.goto("file:///Users/melvynx/Developer/agent-benchmarks/benchmarks/distributed-systems-playground/2026-09-21-cursor-agent-grok-4-7-high/index.html");
await page.waitForTimeout(400);
const title = await page.title();
const h1 = await page.textContent("h1");
const diag = await page.textContent("#diag-summary");
const selfTest = await page.evaluate(() => window.__DSP__.runSelfTest());
await page.waitForTimeout(1200);
const wide = await page.screenshot({ fullPage: true });
const widePath = await saveScreenshot(wide, "dsp-wide.png");
const live = await page.evaluate(() => {
  const dsp = window.__DSP__;
  const out = { scenarios: {}, reset: null, pause: null, faults: null, dupes: null, poison: null };
  const names = ["healthy", "flash-crowd", "database-outage", "poison-message", "stale-replica"];
  for (const name of names) {
    dsp.setScenario(name);
    dsp.step(1500);
    const snap = dsp.snapshot();
    out.scenarios[name] = {
      scenario: snap.scenario,
      time: snap.time,
      queue: snap.queue.depth,
      workers: snap.workers.length,
      primaryUp: snap.primary.up,
      circuit: snap.circuitBreaker.state,
      lag: snap.replica.lagMs,
      dlq: snap.deadLetterQueue.length,
      completed: snap.metrics.completed,
      finite: Number.isFinite(snap.metrics.throughput) && Number.isFinite(snap.metrics.p95Latency) && Number.isFinite(snap.metrics.errorRate)
    };
  }
  dsp.reset(42);
  dsp.step(700);
  const a = JSON.stringify(dsp.snapshot());
  dsp.reset(42);
  dsp.step(700);
  const b = JSON.stringify(dsp.snapshot());
  out.reset = { equal: a === b, time: dsp.snapshot().time };

  dsp.setScenario("healthy");
  const playBtn = document.getElementById("btn-play");
  playBtn.click();
  const t0 = dsp.snapshot().time;
  return Object.assign(out, { pausedAt: t0, playingLabel: document.getElementById("strip-play-label").textContent });
});
await page.waitForTimeout(350);
const afterPause = await page.evaluate(() => {
  const t = window.__DSP__.snapshot().time;
  document.getElementById("btn-step").click();
  const t2 = window.__DSP__.snapshot().time;
  return { t, t2 };
});
const faults = await page.evaluate(() => {
  const dsp = window.__DSP__;
  dsp.setScenario("healthy");
  dsp.step(50);
  document.getElementById("btn-db-fail").click();
  const id = dsp.sendRequest({ op: "write", key: "acct", tenantId: "tn-1", idempotencyKey: "ik-ui-down", value: 7 });
  dsp.step(4000);
  const down = dsp.snapshot();
  const committedWhileDown = !!down.primary.records.find((r) => r.idempotencyKey === "ik-ui-down");
  document.getElementById("btn-db-recover").click();
  dsp.step(8000);
  const up = dsp.snapshot();
  const req = up.requests.find((r) => r.id === id);
  document.getElementById("btn-dupes").click();
  dsp.step(6000);
  const dup = dsp.snapshot();
  const invoice = dup.primary.records.filter((r) => r.key === "invoice" && String(r.idempotencyKey).startsWith("ik-burst-"));
  return {
    downUp: down.primary.up,
    committedWhileDown,
    statusWhileDown: down.requests.find((r) => r.id === id)?.status,
    recoveredUp: up.primary.up,
    afterRecoverStatus: req && req.status,
    dupes: dup.metrics.duplicatesPrevented,
    invoiceCommits: invoice.length
  };
});
const poison = await page.evaluate(() => {
  const dsp = window.__DSP__;
  dsp.setScenario("poison-message");
  dsp.step(15000);
  const before = dsp.snapshot();
  document.getElementById("btn-poison-clear").click();
  const dead = before.deadLetterQueue[0];
  if (dead) {
    document.querySelector("[data-replay]")?.click();
  }
  dsp.step(4000);
  const after = dsp.snapshot();
  const req = dead && after.requests.find((r) => r.id === dead.requestId);
  return {
    dlqBefore: before.deadLetterQueue.length,
    status: req && req.status,
    commit: req ? after.primary.records.some((r) => r.idempotencyKey === req.idempotencyKey) : false,
    dlqAfter: after.deadLetterQueue.length
  };
});
await page.setViewportSize({ width: 720, height: 900 });
await page.waitForTimeout(200);
const narrow = await page.screenshot({ fullPage: true });
const narrowPath = await saveScreenshot(narrow, "dsp-narrow.png");
const boxes = await page.evaluate(() => {
  const ids = ["node-clients","node-gateway","node-queue","node-workers","node-primary","node-replica","node-cache","node-retry","node-dlq","node-obs"];
  return ids.map((id) => {
    const r = document.getElementById(id).getBoundingClientRect();
    return { id, w: Math.round(r.width), h: Math.round(r.height), x: Math.round(r.x), y: Math.round(r.y) };
  });
});
console.log(JSON.stringify({ title, h1, diag, selfPassed: selfTest.passed, selfFail: selfTest.tests.filter(t => !t.pass), errors, live, afterPause, faults, poison, boxes, widePath, narrowPath }, null, 2));
