const fs = require('fs');
const vm = require('vm');
const html = fs.readFileSync('index.html','utf8');
const m = html.match(/<script>([\s\S]*)<\/script>/);
let script = m[1];
script = script.replace('function boot() {', 'function boot() { if (globalThis.__NO_BOOT) return;');
script = script.replace(/\n\s*boot\(\);\n\}\)\(\);?\s*$/, '\n  globalThis.__api = { create, step, snapshot, setScenario, executeSelfTest };\n})();');
const window = { matchMedia: () => ({ matches: false }), addEventListener(){}, devicePixelRatio: 1 };
const document = { getElementById: () => null, addEventListener(){}, hidden: false, body: { addEventListener(){} }, querySelectorAll: () => [] };
const context = vm.createContext({ console, Math, Number, JSON, Object, Array, String, Error, window, document, requestAnimationFrame(){return 1}, setTimeout });
context.globalThis = context;
context.__NO_BOOT = true;
vm.runInContext(script, context);
const api = context.globalThis.__api;
const result = api.executeSelfTest();
console.log('SELF', result.passed, result.tests.filter(t => !t.pass).map(t => t.name + ': ' + t.detail));
let s = api.setScenario(api.create(7,'healthy'), 'flash-crowd');
api.step(s, 3200);
const snap = api.snapshot(s);
console.log(JSON.stringify({ q: snap.queue.depth, max: snap.queue.max, rej: snap.gateway.rejected, thr: snap.gateway.throttled, tokens: +snap.gateway.tokens.toFixed(2), workers: snap.workers.length, traffic: snap.trafficRate }));
